def resolve(path, cwd, links):
    if path is None or cwd is None or links is None:
        return None

    # Start with the initial path
    if path.startswith('/'):
        current = path
    else:
        current = cwd.rstrip('/') + '/' + path

    # Track link resolution count to prevent infinite loops
    link_count = 0
    max_links = 8

    while True:
        # Split into components
        parts = current.split('/')
        resolved_parts = []

        for part in parts:
            # Skip empty components and '.'
            if part == '' or part == '.':
                continue
            # Handle '..'
            elif part == '..':
                if resolved_parts:
                    resolved_parts.pop()
                # If at root, '..' stays at root
            else:
                # Append the component
                resolved_parts.append(part)

            # Build current path up to this component
            current_path = '/' + '/'.join(resolved_parts)

            # Check if this path is a symlink
            if current_path in links:
                if link_count >= max_links:
                    return None

                link_count += 1
                target = links[current_path]

                # Determine the absolute target path
                if target.startswith('/'):
                    # Absolute symlink target
                    target_path = target
                else:
                    # Relative symlink target - relative to the directory containing the link
                    if '/' in current_path:
                        link_dir = current_path.rsplit('/', 1)[0]
                    else:
                        link_dir = '/'
                    target_path = link_dir.rstrip('/') + '/' + target

                # Recursively resolve the target
                remaining = '/'.join(parts[parts.index(part) + 1:]) if part in parts else ''
                if remaining:
                    target_path = target_path.rstrip('/') + '/' + remaining

                result = resolve(target_path, cwd, links)
                if result is None:
                    return None
                return result

        # No more symlinks found, we're done
        current = '/' + '/'.join(resolved_parts)
        break

    # Return root as '/', otherwise remove trailing slash
    if current == '/':
        return '/'
    return current.rstrip('/')

